<?php
require_once __DIR__.'/includes/learning-tools.php';learn_ensure_tables();$error='';$editing=max(0,(int)($_GET['id']??$_POST['lesson_id']??0));$lesson=null;$items=[];
if($editing){$q=learn_db()->prepare('SELECT * FROM custom_lessons WHERE id=? AND user_id=?');$q->execute([$editing,$learnUserId]);$lesson=$q->fetch();if($lesson){$q=learn_db()->prepare('SELECT * FROM custom_lesson_items WHERE custom_lesson_id=? ORDER BY order_index');$q->execute([$editing]);$items=$q->fetchAll();}}
if($_SERVER['REQUEST_METHOD']==='POST'){learn_verify_csrf();$action=(string)($_POST['action']??'save');if($action==='answer'&&$lesson&&$items){$score=0;$count=count($items);foreach($items as $it){$ans=(string)($_POST['answers'][$it['id']]??'');if(hash_equals((string)$it['answer'],$ans))$score++;}try{$q=learn_db()->prepare('INSERT INTO custom_lesson_progress(custom_lesson_id,user_id,score,question_count) VALUES(?,?,?,?)');$q->execute([$editing,$learnUserId,$score,$count]);if($count>0 && $score===$count)learn_record_practice($learnUserId,0);}catch(Throwable $e){error_log('[custom lesson progress] '.$e->getMessage());}$result=['score'=>$score,'count'=>$count];$_SESSION['custom_result']=$result;header('Location: custom-lesson.php?id='.$editing.'&result=1');exit;}
if($action==='save'){$title=trim((string)($_POST['title']??''));$description=trim((string)($_POST['description']??''));$prompts=$_POST['prompt']??[];$answers=$_POST['answer']??[];$opts=$_POST['options']??[];$valid=[];for($i=0;$i<min(10,count($prompts));$i++){$pr=trim((string)($prompts[$i]??''));$an=trim((string)($answers[$i]??''));$op=array_values(array_filter(array_map('trim',explode('|',(string)($opts[$i]??''))),fn($x)=>$x!==''));if($pr!==''&&$an!==''&&count($op)>=2){if(!in_array($an,$op,true))$op[]=$an;$op=array_values(array_unique($op));if(count($op)>6){$op=array_slice($op,0,5);if(!in_array($an,$op,true))$op[]=$an;}$valid[]=[$pr,$an,$op];}}if(mb_strlen($title)<3||mb_strlen($title)>120)$error='El título debe tener entre 3 y 120 caracteres.';elseif(!$valid)$error='Añade al menos una pregunta, respuesta correcta y dos opciones separadas por |.';else{try{learn_db()->beginTransaction();if($editing&&$lesson){learn_db()->prepare('UPDATE custom_lessons SET title=?,description=? WHERE id=? AND user_id=?')->execute([$title,$description,$editing,$learnUserId]);learn_db()->prepare('DELETE FROM custom_lesson_items WHERE custom_lesson_id=?')->execute([$editing]);$newId=$editing;}else{$q=learn_db()->prepare('INSERT INTO custom_lessons(user_id,title,description) VALUES(?,?,?)');$q->execute([$learnUserId,$title,$description]);$newId=(int)learn_db()->lastInsertId();}$q=learn_db()->prepare('INSERT INTO custom_lesson_items(custom_lesson_id,prompt,answer,options_json,order_index) VALUES(?,?,?,?,?)');foreach($valid as $i=>$it)$q->execute([$newId,$it[0],$it[1],json_encode($it[2],JSON_UNESCAPED_UNICODE),$i]);learn_db()->commit();header('Location: custom-lesson.php?id='.$newId.'&saved=1');exit;}catch(Throwable $e){if(learn_db()->inTransaction())learn_db()->rollBack();$error='No se pudo guardar. Comprueba que la base de datos permite crear las tablas de lecciones personales.';error_log('[custom lesson] '.$e->getMessage());}}}
}
if($editing&&!$lesson&&!isset($_GET['saved'])){$error='No se encontró esa lección personal o no te pertenece.';$editing=0;}
learn_header($lesson?'Editar lección personal':'Crear una lección','Crea un cuestionario privado con respuestas de opción múltiple.');if(isset($_GET['saved']))learn_flash('Lección guardada correctamente.');if(isset($_GET['result'])&&isset($_SESSION['custom_result'])){$r=$_SESSION['custom_result'];unset($_SESSION['custom_result']);echo '<section class="learn-panel"><div class="learn-result-score">'.(int)round($r['score']/max(1,$r['count'])*100).'%</div><p class="learn-muted">Resultado: '.(int)$r['score'].' de '.(int)$r['count'].' respuestas correctas.</p><a class="learn-button" href="custom-lesson.php?id='.$editing.'">Volver a practicar</a></section>';}
if($error)learn_flash($error);
if($lesson&&$items){echo '<section class="learn-panel"><h2>'.learn_h($lesson['title']).'</h2><p class="learn-muted">'.learn_h($lesson['description']).'</p><form method="post" class="learn-form">'.learn_csrf().'<input type="hidden" name="action" value="answer">';foreach($items as $it){$options=json_decode($it['options_json'],true)?:[$it['answer']];shuffle($options);echo '<fieldset class="learn-question"><legend>'.learn_h($it['prompt']).'</legend><div class="learn-options">';foreach($options as $o)echo '<label class="learn-option"><input type="radio" required name="answers['.(int)$it['id'].']" value="'.learn_h($o).'">'.learn_h($o).'</label>';echo '</div></fieldset>'; }echo '<button class="learn-button">Calificar respuestas</button></form></section><p><a class="learn-button secondary" href="custom-lesson.php">Crear otra</a></p>';}
else{echo '<form method="post" class="learn-panel learn-form">'.learn_csrf().'<input type="hidden" name="action" value="save"><input type="hidden" name="lesson_id" value="'.$editing.'"><label>Título<input name="title" required maxlength="120" value="'.learn_h($lesson['title']??'').'" placeholder="Ej. Repaso de saludos"></label><label>Descripción<textarea name="description" maxlength="500">'.learn_h($lesson['description']??'').'</textarea></label><p class="learn-muted">Cada pregunta admite opciones separadas por el símbolo |. La respuesta correcta debe coincidir con una opción.</p>';
for($i=0;$i<5;$i++){$it=$items[$i]??[];$opts=isset($it['options_json'])?(json_decode($it['options_json'],true)?:[]):[];echo '<fieldset class="learn-question"><legend>Pregunta '.($i+1).'</legend><label>Enunciado<input name="prompt[]" maxlength="255" value="'.learn_h($it['prompt']??'').'" placeholder="¿Qué palabra estás repasando?"></label><label>Respuesta correcta<input name="answer[]" maxlength="255" value="'.learn_h($it['answer']??'').'" placeholder="Hola"></label><label>Opciones (separadas por |)<input name="options[]" value="'.learn_h(implode(' | ',$opts)).'" placeholder="Hola | Adiós | Gracias"></label></fieldset>'; }echo '<button class="learn-button">Guardar lección →</button></form>';}
learn_footer();
